const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cairnsPoint = ee.Geometry.Point(145.7708, -16.9203); // Approximate center of Cairns
  const cooktownPoint = ee.Geometry.Point(145.248920, -15.475923);

  const startDate = '2025-01-31';
  const endDate = '2025-02-04'; // Inclusive

  const scale = 5000; // GPM resolution is ~10km, using 5km for computation

  // 2. Data Acquisition & Check
  const gpmCollection = ee.ImageCollection("NASA/GPM_L3/IMERG_FINAL_V06")
    .filterDate(startDate, ee.Date(endDate).advance(1, 'day')) // Filter to include endDate
    .select('precipitationCal');

  const collectionSize = await gpmCollection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No GPM IMERG data found for the specified date range.");
    console.log("C1");
    return;
  }

  // Aggregate rainfall over the period by summing the daily precipitation.
  // Each pixel in the resulting image will represent total rainfall for the period.
  const totalRainfallImage = gpmCollection.sum();

  // 3. Processing & Calculation for Cairns
  const cairnsRainfallResult = await totalRainfallImage.reduceRegion({
    reducer: ee.Reducer.mean(), // Use mean to get the value at the point
    geometry: cairnsPoint,
    scale: scale,
    tileScale: 16 // Increase tileScale for larger regions if needed, but points are fine
  }).getInfo();

  const cairnsRainfall = cairnsRainfallResult ? cairnsRainfallResult.precipitationCal : null;

  // 4. Processing & Calculation for Cooktown
  const cooktownRainfallResult = await totalRainfallImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: cooktownPoint,
    scale: scale,
    tileScale: 16
  }).getInfo();

  const cooktownRainfall = cooktownRainfallResult ? cooktownRainfallResult.precipitationCal : null;

  // 5. Validation & Final Answer
  if (cairnsRainfall === null || isNaN(cairnsRainfall) || cooktownRainfall === null || isNaN(cooktownRainfall)) {
    console.log("Calculation failure: Rainfall value is null or NaN for one or both locations.");
    console.log(`Cairns Rainfall: ${cairnsRainfall}, Cooktown Rainfall: ${cooktownRainfall}`);
    console.log("C3");
    return;
  }

  console.log(`GPM images: ${collectionSize}`);
  console.log(`Cairns total rainfall (mm): ${cairnsRainfall.toFixed(2)}`);
  console.log(`Cooktown total rainfall (mm): ${cooktownRainfall.toFixed(2)}`);

  if (cairnsRainfall > cooktownRainfall) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
